import {
  Combobox as ComboboxPrimitive,
  type CollectionItem,
  type ComboboxRootProps as ArkComboboxRootProps,
  type ComboboxRootProviderProps as ArkComboboxRootProviderProps,
  useCombobox,
  useComboboxContext,
  useComboboxItemContext,
} from '@ark-ui/solid/combobox';
import { ark, type HTMLArkProps } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import { CheckIcon, ChevronUpDownIcon } from '@/lib/moduix/icons/ui/Icons';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './Combobox.module.css';

type ComboboxRootProps<T extends CollectionItem> = ArkComboboxRootProps<T> & OverlayPortalProps;
type ComboboxRootProviderProps<T extends CollectionItem> = ArkComboboxRootProviderProps<T> &
  OverlayPortalProps;

function Combobox<T extends CollectionItem>(props: ComboboxRootProps<T>) {
  const [local, others] = splitProps(props, [
    'children',
    'class',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <ComboboxPrimitive.Root
        class={clsx(styles.root, local.class)}
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
        data-slot="combobox-root"
      >
        {local.children}
      </ComboboxPrimitive.Root>
    </OverlayPortalProvider>
  );
}

function ComboboxRootProvider<T extends CollectionItem>(props: ComboboxRootProviderProps<T>) {
  const [local, others] = splitProps(props, [
    'children',
    'class',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <ComboboxPrimitive.RootProvider
        class={clsx(styles.root, local.class)}
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
        data-slot="combobox-root-provider"
      >
        {local.children}
      </ComboboxPrimitive.RootProvider>
    </OverlayPortalProvider>
  );
}

function ComboboxLabel(props: ComponentProps<typeof ComboboxPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="combobox-label"
    />
  );
}

function ComboboxControl(props: ComponentProps<typeof ComboboxPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="combobox-control"
    />
  );
}

function ComboboxInput(props: ComponentProps<typeof ComboboxPrimitive.Input>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ComboboxPrimitive.Input
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.input, local.class)}
      {...others}
      data-slot="combobox-input"
    />
  );
}

function ComboboxClearTrigger(props: ComponentProps<typeof ComboboxPrimitive.ClearTrigger>) {
  const [local, others] = splitProps(props, [
    'aria-label',
    'aria-labelledby',
    'asChild',
    'children',
    'class',
  ]);
  const triggerClass = () => clsx(styles.clearTrigger, local.class);

  if (local.asChild) {
    return (
      <ComboboxPrimitive.ClearTrigger
        asChild={local.asChild}
        aria-label={local['aria-label']}
        aria-labelledby={local['aria-labelledby']}
        class={triggerClass()}
        {...others}
        data-slot="combobox-clear-trigger"
      >
        {local.children}
      </ComboboxPrimitive.ClearTrigger>
    );
  }

  return (
    <ComboboxPrimitive.ClearTrigger
      asChild={(triggerProps) => {
        const resolvedProps = triggerProps();

        return (
          <CloseButton
            {...resolvedProps}
            aria-label={
              local['aria-label'] ??
              (local['aria-labelledby'] == null ? a11yLabels.clearSelection : undefined)
            }
            aria-labelledby={local['aria-labelledby']}
          >
            {local.children}
          </CloseButton>
        );
      }}
      class={triggerClass()}
      {...others}
      data-slot="combobox-clear-trigger"
    />
  );
}

function ComboboxTrigger(props: ComponentProps<typeof ComboboxPrimitive.Trigger>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <ComboboxPrimitive.Trigger
      class={clsx(styles.trigger, local.class)}
      {...others}
      data-slot="combobox-trigger"
    >
      {resolvedChildren() ?? <ChevronUpDownIcon />}
    </ComboboxPrimitive.Trigger>
  );
}

function ComboboxPositioner(props: ComponentProps<typeof ComboboxPrimitive.Positioner>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <OverlayPortal>
      <ComboboxPrimitive.Positioner
        class={clsx(styles.positioner, local.class)}
        {...others}
        data-slot="combobox-positioner"
      />
    </OverlayPortal>
  );
}

function ComboboxContent(props: ComponentProps<typeof ComboboxPrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="combobox-content"
    />
  );
}

function ComboboxEmpty(props: ComponentProps<typeof ComboboxPrimitive.Empty>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.Empty
      class={clsx(styles.empty, local.class)}
      {...others}
      data-slot="combobox-empty"
    />
  );
}

function ComboboxStatus(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div class={clsx(styles.status, local.class)} {...others} data-slot="combobox-status" />
  );
}

function ComboboxList(props: ComponentProps<typeof ComboboxPrimitive.List>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.List
      class={clsx(styles.list, local.class)}
      {...others}
      data-slot="combobox-list"
    />
  );
}

function ComboboxItemGroup(props: ComponentProps<typeof ComboboxPrimitive.ItemGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.ItemGroup
      class={clsx(styles.itemGroup, local.class)}
      {...others}
      data-slot="combobox-item-group"
    />
  );
}

function ComboboxItemGroupLabel(props: ComponentProps<typeof ComboboxPrimitive.ItemGroupLabel>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.ItemGroupLabel
      class={clsx(styles.itemGroupLabel, local.class)}
      {...others}
      data-slot="combobox-item-group-label"
    />
  );
}

function ComboboxItem(props: ComponentProps<typeof ComboboxPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-slot="combobox-item"
    />
  );
}

function ComboboxItemText(props: ComponentProps<typeof ComboboxPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ComboboxPrimitive.ItemText
      class={clsx(styles.itemText, local.class)}
      {...others}
      data-slot="combobox-item-text"
    />
  );
}

function ComboboxItemIndicator(props: ComponentProps<typeof ComboboxPrimitive.ItemIndicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <ComboboxPrimitive.ItemIndicator
      class={clsx(styles.itemIndicator, local.class)}
      {...others}
      data-slot="combobox-item-indicator"
    >
      {resolvedChildren() ?? <CheckIcon />}
    </ComboboxPrimitive.ItemIndicator>
  );
}

type ComboboxOptionProps = Omit<
  ComponentProps<typeof ComboboxPrimitive.Item>,
  'asChild' | 'children'
> & {
  children: JSX.Element;
  indicator?: JSX.Element | false;
};

function ComboboxOption(props: ComboboxOptionProps) {
  const [local, others] = splitProps(props, ['children', 'indicator']);

  return (
    <ComboboxItem {...others}>
      <ComboboxItemText>{local.children}</ComboboxItemText>
      {local.indicator !== false && (
        <ComboboxItemIndicator>{local.indicator}</ComboboxItemIndicator>
      )}
    </ComboboxItem>
  );
}

const ComboboxContext = ComboboxPrimitive.Context;
const ComboboxItemContext = ComboboxPrimitive.ItemContext;

export {
  Combobox,
  ComboboxClearTrigger,
  ComboboxContext,
  ComboboxContent,
  ComboboxControl,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxItemContext,
  ComboboxItemGroup,
  ComboboxItemGroupLabel,
  ComboboxItemIndicator,
  ComboboxItemText,
  ComboboxLabel,
  ComboboxList,
  ComboboxOption,
  ComboboxPositioner,
  ComboboxRootProvider,
  ComboboxStatus,
  ComboboxTrigger,
  useCombobox,
  useComboboxContext,
  useComboboxItemContext,
};

export type { ComboboxOptionProps, ComboboxRootProps, ComboboxRootProviderProps };

export type {
  ComboboxClearTriggerProps,
  ComboboxContentProps,
  ComboboxContextProps,
  ComboboxControlProps,
  ComboboxEmptyProps,
  ComboboxHighlightChangeDetails,
  ComboboxInputProps,
  ComboboxInputValueChangeDetails,
  ComboboxItemContextProps,
  ComboboxItemGroupLabelProps,
  ComboboxItemGroupProps,
  ComboboxItemIndicatorProps,
  ComboboxItemProps,
  ComboboxItemTextProps,
  ComboboxLabelProps,
  ComboboxListProps,
  ComboboxOpenChangeDetails,
  ComboboxPositionerProps,
  ComboboxSelectionDetails,
  ComboboxTriggerProps,
  ComboboxValueChangeDetails,
  UseComboboxContext,
  UseComboboxItemContext,
  UseComboboxProps,
  UseComboboxReturn,
} from '@ark-ui/solid/combobox';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: var(--moduix-combobox-width, 16rem);
    max-width: 100%;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-1-5);
    color: var(--moduix-color-foreground);
  }

  .label {
    display: inline-flex;
    align-items: center;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .control {
    --_combobox-action-size: var(--moduix-combobox-action-size, var(--moduix-size-xs));
    --_combobox-action-offset: var(--moduix-spacing-2);

    position: relative;
    display: flex;
    width: 100%;
    min-width: 0;
    align-items: center;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-combobox-radius, var(--moduix-radius-md));
    background-color: var(--moduix-color-background);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &[data-state='open'],
    &[data-focus] {
      border-color: var(--moduix-color-ring);
      outline-color: var(--moduix-color-ring);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);
      outline-color: var(--moduix-color-destructive);
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .input {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    height: var(--moduix-combobox-control-height, var(--moduix-size-md));
    margin: 0;
    border: 0;
    border-radius: inherit;
    padding-inline: var(--moduix-spacing-3-5);
    background: transparent;
    color: inherit;
    font: inherit;
    outline: 0;

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }
  }

  /* Reserve room for one action, then for both; the text keeps a 12px gap before them. */
  .control:is(:has(.trigger), :has(.clearTrigger)) .input {
    padding-inline-end: calc(
      var(--_combobox-action-offset) + var(--_combobox-action-size) + var(--moduix-spacing-3)
    );
  }

  .control:has(.trigger):has(.clearTrigger) .input {
    padding-inline-end: calc(
      var(--_combobox-action-offset) + var(--_combobox-action-size) * 2 +
        var(--moduix-spacing-0-5) + var(--moduix-spacing-3)
    );
  }

  .trigger,
  .clearTrigger {
    position: absolute;
    top: 50%;
    inset-inline-end: var(--_combobox-action-offset);
    transform: translateY(-50%);
  }

  .control:has(.trigger) .clearTrigger {
    inset-inline-end: calc(
      var(--_combobox-action-offset) + var(--_combobox-action-size) + var(--moduix-spacing-0-5)
    );
  }

  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    width: var(--_combobox-action-size);
    height: var(--_combobox-action-size);
    align-items: center;
    justify-content: center;
    margin: 0;
    border: 0;
    border-radius: var(--moduix-radius-sm);
    padding: 0;
    background: transparent;
    color: var(--moduix-color-muted-foreground);
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-offset);
    }

    &:not([data-disabled]) {
      @media (hover: hover) {
        &:hover {
          background-color: var(--moduix-color-muted);
          color: var(--moduix-color-foreground);
        }
      }
    }

    &[data-disabled] {
      cursor: default;
    }
  }

  .clearTrigger {
    --moduix-close-button-size: var(--_combobox-action-size);

    &[hidden] {
      display: none;
    }
  }

  .positioner {
    z-index: var(--z-index);
  }

  .content {
    box-sizing: border-box;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    display: flex;
    min-width: var(--reference-width);
    max-width: var(--available-width);
    max-height: min(var(--moduix-combobox-content-max-height, 24rem), var(--available-height));
    flex-direction: column;
    overflow: auto;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-combobox-radius, var(--moduix-radius-md));
    padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
    background-color: var(--moduix-color-popover);
    box-shadow: var(--moduix-shadow-lg);
    color: var(--moduix-color-popover-foreground);
    transform-origin: var(--transform-origin);
    outline: 0;
    overscroll-behavior: contain;
    scroll-padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .list {
    display: flex;
    min-height: 0;
    flex-direction: column;
    outline: 0;

    &[data-empty] {
      display: none;
    }
  }

  .empty,
  .status {
    padding-block: var(--moduix-spacing-1);
    padding-inline: var(--moduix-spacing-4);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .itemGroup {
    display: flex;
    flex-direction: column;

    & + & {
      margin-block-start: var(--moduix-spacing-2);
    }
  }

  .itemGroupLabel {
    position: sticky;
    top: calc(-1 * var(--moduix-popup-list-padding-y, var(--moduix-spacing-1)));
    z-index: 1;
    padding-block: var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-spacing-2-5);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-popup-group-label-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs));
  }

  .item {
    box-sizing: border-box;
    position: relative;
    display: flex;
    min-height: var(--moduix-popup-item-min-height, var(--moduix-size-sm));
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-spacing-2);
    margin-inline: var(--moduix-spacing-1);
    border-radius: var(--moduix-radius-sm);
    padding-block: var(--moduix-popup-item-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3));
    font-size: var(--moduix-popup-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm));
    outline: 0;
    cursor: default;
    user-select: none;

    &[data-highlighted] {
      background-color: var(--moduix-color-accent);
      color: var(--moduix-color-accent-foreground);
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
      pointer-events: none;
    }
  }

  .itemText {
    min-width: 0;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .itemIndicator {
    display: inline-flex;
    width: var(--moduix-spacing-3);
    height: var(--moduix-spacing-3);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;

    & > svg {
      width: 100%;
      height: 100%;
    }
  }
}
